with flagged as (select *, case when txn_time - lag(txn_time) over (partition by account_id order by txn_time, id) > interval '14' day then 1 else 0 end as is_new_burst from transactions), sessionized as (select id, account_id, amount, txn_time, merchant, is_flagged, sum(is_new_burst) over (partition by account_id order by txn_time, id rows between unbounded preceding and current row) as island_id from flagged) select date_trunc('month', txn_time) as activity_month, avg(amount) as avg_amount, max(island_id) filter (where merchant = 'Starbucks') as starbucks_max_island_id from sessionized group by date_trunc('month', txn_time) having starbucks_max_island_id >= 0;
